const orders = [
  ...($('Wait').first().json.orders || []),
  ...($('Get Otto orders').first().json.resources || [])
];

const href = $input.first().json.links.find(item => item.rel === 'next').href

return { orders, href };

const productsIds = $input.item.json.products
const website = 31;

const shipPrice = $('Split orders').item.json.initialDeliveryFees[0].deliveryFeeAmount.amount;

const orderProducts = $('Split orders').item.json.positionItems.map(productItem => {
  const { sku, ean } = productItem.product;
  const product_id = productsIds.find(item => item.default_code === sku ||
                                              item.x_studio_variation_id === sku ||
                                              item.barcode === ean);

  const product_uom_qty = 1;
  const price_unit = productItem.itemValueGrossPrice.amount;

  return {
    product_id: product_id?.id || null,
    product_uom_qty,
    price_unit
  };
});

const mergedProducts = Object.values(orderProducts.reduce((acc, product) => {
  const { product_id, product_uom_qty, price_unit } = product;

  if (!acc[product_id]) {
    acc[product_id] = {
      product_id,
      product_uom_qty: 0,
      price_unit
    };
  };

  acc[product_id].product_uom_qty += product_uom_qty;

  return acc;
  }, {})
);

const products = mergedProducts.map(item => ([0, 0, { ...item }]));

// Доставка
products.push([0, 0,
{
  product_id: 1,
  product_uom_qty: 1,
  price_unit: shipPrice
}]);

return {
  website,
  products 
};

